{"file_path":"src/adapters/sqlite-catalog-repository.ts","content":"import { DatabaseSync } from 'node:sqlite';
import type { CatalogRepository } from '../domain/contracts.js';

const MIGRATION_VERSION = 1;
const IDENTITY_VERSION = 1;

interface ProductRow {
  readonly Id: number;
  readonly Name: string;
  readonly Brand: string | null;
  readonly Category: string;
}

function canonicalField(value: string): string {
  return value
    .normalize('NFKD')
    .replace(/\p{M}/gu, '')
    .toLocaleLowerCase('en-US')
    .replace(/[^\p{L}\p{N}]+/gu, '');
}

function identityFor(product: ProductRow): {
  readonly canonicalName: string;
  readonly canonicalBrand: string;
  readonly canonicalCategory: string;
  readonly fingerprint: string;
} {
  const canonicalName = canonicalField(product.Name);
  const canonicalBrand = canonicalField(product.Brand ?? '');
  const canonicalCategory = canonicalField(product.Category);
  return {
    canonicalName,
    canonicalBrand,
    canonicalCategory,
    fingerprint: `v${IDENTITY_VERSION}\u0000${canonicalName}\u0000${canonicalBrand}\u0000${canonicalCategory}`,
  };
}

function tableExists(database: DatabaseSync, name: string): boolean {
  return database.prepare("SELECT 1 FROM sqlite_master WHERE type = 'table' AND name = ?").get(name) !== undefined;
}

function assertProductSchema(database: DatabaseSync): void {
  if (!tableExists(database, 'Product')) {
    database.exec(`CREATE TABLE Product (
      Id INTEGER PRIMARY KEY AUTOINCREMENT,
      Name TEXT NOT NULL,
      Brand TEXT,
      Category TEXT NOT NULL
    )`);
    return;
  }
  const columns = database.prepare('PRAGMA table_info(Product)').all() as readonly { readonly name: string }[];
  const names = new Set(columns.map((column) => column.name));
  for (const required of ['Id', 'Name', 'Brand', 'Category']) {
    if (!names.has(required)) throw new Error(`Unsupported Product schema: missing ${required}.`);
  }
}

function assertForeignKeysClean(database: DatabaseSync): void {
  const violations = database.prepare('PRAGMA foreign_key_check').all();
  if (violations.length > 0) throw new Error('Foreign-key validation failed during catalog migration.');
}

function migrateV1(database: DatabaseSync): void {
  assertProductSchema(database);
  const hadSellerProduct = tableExists(database, 'SellerProduct');
  const priorLinkCount = hadSellerProduct
    ? Number((database.prepare('SELECT COUNT(*) AS count FROM SellerProduct').get() as { readonly count: number }).count)
    : 0;

  database.exec(`CREATE TABLE SellerProduct__v1 (
    Id INTEGER PRIMARY KEY AUTOINCREMENT,
    SellerName TEXT NOT NULL,
    ProductId INTEGER NOT NULL REFERENCES Product(Id),
    SellerProductId TEXT NOT NULL,
    UNIQUE(SellerName, SellerProductId)
  )`);
  if (hadSellerProduct) {
    database.exec(`INSERT INTO SellerProduct__v1 (Id, SellerName, ProductId, SellerProductId)
      SELECT Id, SellerName, ProductId, CAST(SellerProductId AS TEXT) FROM SellerProduct`);
  }
  const copiedLinkCount = Number((database.prepare('SELECT COUNT(*) AS count FROM SellerProduct__v1').get() as { readonly count: number }).count);
  if (copiedLinkCount !== priorLinkCount) throw new Error('SellerProduct migration copy count mismatch.');
  if (hadSellerProduct) database.exec('DROP TABLE SellerProduct');
  database.exec('ALTER TABLE SellerProduct__v1 RENAME TO SellerProduct');
  database.exec('CREATE INDEX idx_SellerProduct_ProductId ON SellerProduct(ProductId)');

  database.exec(`CREATE TABLE ProductIdentity (
    ProductId INTEGER PRIMARY KEY REFERENCES Product(Id) ON DELETE CASCADE,
    CanonicalVersion INTEGER NOT NULL,
    CanonicalName TEXT NOT NULL,
    CanonicalBrand TEXT NOT NULL,
    CanonicalCategory TEXT NOT NULL,
    Fingerprint TEXT NOT NULL UNIQUE
  )`);
  const insertIdentity = database.prepare(`INSERT INTO ProductIdentity
    (ProductId, CanonicalVersion, CanonicalName, CanonicalBrand, CanonicalCategory, Fingerprint)
    VALUES (?, ?, ?, ?, ?, ?)`);
  const products = database.prepare('SELECT Id, Name, Brand, Category FROM Product ORDER BY Id').all() as readonly ProductRow[];
  try {
    for (const product of products) {
      const identity = identityFor(product);
      insertIdentity.run(
        product.Id,
        IDENTITY_VERSION,
        identity.canonicalName,
        identity.canonicalBrand,
        identity.canonicalCategory,
        identity.fingerprint,
      );
    }
  } catch (error) {
    if (error instanceof Error && /UNIQUE constraint failed: ProductIdentity\.Fingerprint/.test(error.message)) {
      throw new Error('Product identity backfill collision: multiple existing products share one canonical fingerprint.');
    }
    throw error;
  }
  assertForeignKeysClean(database);
  database.exec(`PRAGMA user_version = ${MIGRATION_VERSION}`);
}

function migrateDatabase(database: DatabaseSync): void {
  database.exec('PRAGMA foreign_keys = ON');
  const version = Number((database.prepare('PRAGMA user_version').get() as { readonly user_version: number }).user_version);
  if (version > MIGRATION_VERSION) {
    throw new Error(`Database schema version ${version} is newer than supported version ${MIGRATION_VERSION}.`);
  }
  if (version === 0) migrateV1(database);
  assertForeignKeysClean(database);
}

/** SQLite adapter that owns transactional schema migration safety. */
export class SqliteCatalogRepository implements CatalogRepository {
  constructor(private readonly databasePath: string) {}

  /** Applies all known ordered migrations durably. */
  migrate(): void {
    const database = new DatabaseSync(this.databasePath);
    try {
      database.exec('PRAGMA foreign_keys = ON');
      database.exec('BEGIN IMMEDIATE');
      migrateDatabase(database);
      database.exec('COMMIT');
    } catch (error) {
      try {
        database.exec('ROLLBACK');
      } catch {
        // Preserve the migration failure as the actionable diagnostic.
      }
      throw error;
    } finally {
      database.close();
    }
  }

  /** Executes migration planning and caller work in a rollback-only transaction. */
  withPlanningTransaction<T>(operation: () => T): T {
    const database = new DatabaseSync(this.databasePath);
    try {
      database.exec('PRAGMA foreign_keys = ON');
      database.exec('BEGIN IMMEDIATE');
      migrateDatabase(database);
      const result = operation();
      database.exec('ROLLBACK');
      return result;
    } catch (error) {
      try {
        database.exec('ROLLBACK');
      } catch {
        // Preserve the original database failure as the actionable diagnostic.
      }
      throw error;
    } finally {
      database.close();
    }
  }
}
"}

